# -----------------------------------------------------------------------------
#  make-android-icons.ps1 — أيقونة التطبيق وشاشة البداية (Phase 7).
#
#  The android/ folder is generated by Capacitor, so its icons are the default
#  template ones. This script draws the ledger mark with System.Drawing (no
#  network, no image editor, no extra dependency) and writes every density the
#  Android project asks for: 5 square icons, 5 round icons, 5 adaptive
#  foregrounds and 11 splash screens. Re-run it whenever the mark changes.
#
#  npm run cap:icons
# -----------------------------------------------------------------------------
Add-Type -AssemblyName System.Drawing

$root = Split-Path -Parent $PSScriptRoot
$res = Join-Path $root 'android\app\src\main\res'
if (-not (Test-Path $res)) {
  Write-Host 'android/ is not generated yet — run: npx cap add android'
  exit 1
}

# Brand colours, same blue the web app uses (css/styles.css --primary).
$blue = [System.Drawing.Color]::FromArgb(255, 21, 101, 192)      # #1565c0
$page = [System.Drawing.Color]::FromArgb(255, 255, 255, 255)
$spine = [System.Drawing.Color]::FromArgb(255, 227, 232, 239)
$gutter = [System.Drawing.Color]::FromArgb(255, 203, 213, 225)
$row = [System.Drawing.Color]::FromArgb(255, 148, 163, 184)
$coin = [System.Drawing.Color]::FromArgb(255, 240, 168, 24)
$coinEdge = [System.Drawing.Color]::FromArgb(255, 200, 138, 14)
$ink = [System.Drawing.Color]::FromArgb(255, 23, 64, 122)

function New-RoundedPath([single]$x, [single]$y, [single]$w, [single]$h, [single]$r) {
  $p = New-Object System.Drawing.Drawing2D.GraphicsPath
  $d = $r * 2
  $p.AddArc($x, $y, $d, $d, 180, 90)
  $p.AddArc($x + $w - $d, $y, $d, $d, 270, 90)
  $p.AddArc($x + $w - $d, $y + $h - $d, $d, $d, 0, 90)
  $p.AddArc($x, $y + $h - $d, $d, $d, 90, 90)
  $p.CloseFigure()
  return $p
}

# The mark itself, drawn inside a square of side $s whose top-left corner is
# ($ox,$oy). Everything is proportional, so it stays identical at 48px and 432px.
function Draw-Mark([System.Drawing.Graphics]$g, [single]$ox, [single]$oy, [single]$s) {
  $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias

  $book = New-RoundedPath ($ox + 0.10 * $s) ($oy + 0.18 * $s) (0.80 * $s) (0.64 * $s) (0.06 * $s)
  $b = New-Object System.Drawing.SolidBrush($page)
  $g.FillPath($b, $book)

  # The spine sits on the right: this book is read right-to-left.
  $sp = New-RoundedPath ($ox + 0.80 * $s) ($oy + 0.18 * $s) (0.10 * $s) (0.64 * $s) (0.045 * $s)
  $bs = New-Object System.Drawing.SolidBrush($spine)
  $g.FillPath($bs, $sp)

  $pg = New-Object System.Drawing.Pen($gutter, [single](0.018 * $s))
  $g.DrawLine($pg, [single]($ox + 0.52 * $s), [single]($oy + 0.24 * $s), [single]($ox + 0.52 * $s), [single]($oy + 0.76 * $s))

  # Ledger rows on the left page.
  $pr = New-Object System.Drawing.Pen($row, [single](0.032 * $s))
  $pr.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
  $pr.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
  foreach ($fy in 0.34, 0.46, 0.58) {
    $g.DrawLine($pr, [single]($ox + 0.18 * $s), [single]($oy + $fy * $s), [single]($ox + 0.46 * $s), [single]($oy + $fy * $s))
  }

  # A coin on the right page, then a settled tick under it.
  $r = [single](0.105 * $s)
  $ccx = $ox + 0.68 * $s
  $ccy = $oy + 0.40 * $s
  $bc = New-Object System.Drawing.SolidBrush($coin)
  $g.FillEllipse($bc, ($ccx - $r), ($ccy - $r), ($r * 2), ($r * 2))
  $pc = New-Object System.Drawing.Pen($coinEdge, [single](0.022 * $s))
  $g.DrawEllipse($pc, [single]($ccx - $r * 0.62), [single]($ccy - $r * 0.62), [single]($r * 1.24), [single]($r * 1.24))

  $pt = New-Object System.Drawing.Pen($ink, [single](0.038 * $s))
  $pt.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
  $pt.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
  $g.DrawLines($pt, @(
      [System.Drawing.PointF]::new([single]($ox + 0.60 * $s), [single]($oy + 0.66 * $s)),
      [System.Drawing.PointF]::new([single]($ox + 0.67 * $s), [single]($oy + 0.73 * $s)),
      [System.Drawing.PointF]::new([single]($ox + 0.80 * $s), [single]($oy + 0.56 * $s))
    ))

  @($b, $bs, $pg, $pr, $bc, $pc, $pt) | ForEach-Object { $_.Dispose() }
  $book.Dispose(); $sp.Dispose()
}

function Save-Square($path, $w, $h, [bool]$withBg, [single]$mark, [bool]$circle = $false) {
  $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
  $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
  if ($withBg) {
    if ($circle) {
      $b = New-Object System.Drawing.SolidBrush($blue)
      $g.FillEllipse($b, 0, 0, $w, $h); $b.Dispose()
    }
    else {
      $rp = New-RoundedPath 0 0 $w $h ([single]($w * 0.18))
      $b = New-Object System.Drawing.SolidBrush($blue)
      $g.FillPath($b, $rp); $b.Dispose(); $rp.Dispose()
    }
  }
  else { $g.Clear([System.Drawing.Color]::Transparent) }

  $s = [single]($mark * [Math]::Min($w, $h))
  Draw-Mark $g ([single](($w - $s) / 2)) ([single](($h - $s) / 2)) $s
  $g.Dispose()
  $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
  $bmp.Dispose()
  Write-Host ("  wrote " + (Split-Path $path -Leaf) + " " + $w + "x" + $h)
}

$dens = @{ mdpi = 48; hdpi = 72; xhdpi = 96; xxhdpi = 144; xxxhdpi = 192 }
$fgr = @{ mdpi = 108; hdpi = 162; xhdpi = 216; xxhdpi = 324; xxxhdpi = 432 }

Write-Host 'launcher icons:'
foreach ($k in $dens.Keys) {
  $dir = Join-Path $res "mipmap-$k"
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir | Out-Null }
  Save-Square (Join-Path $dir 'ic_launcher.png') $dens[$k] $dens[$k] $true 0.78
  Save-Square (Join-Path $dir 'ic_launcher_round.png') $dens[$k] $dens[$k] $true 0.74 $true
  # The adaptive foreground keeps the mark inside the safe 66% circle.
  Save-Square (Join-Path $dir 'ic_launcher_foreground.png') $fgr[$k] $fgr[$k] $false 0.50
}

Write-Host 'splash screens:'
$splash = @{
  'drawable'                 = @(480, 320)
  'drawable-land-mdpi'       = @(480, 320)
  'drawable-land-hdpi'       = @(800, 480)
  'drawable-land-xhdpi'      = @(1280, 720)
  'drawable-land-xxhdpi'     = @(1600, 960)
  'drawable-land-xxxhdpi'    = @(1920, 1280)
  'drawable-port-mdpi'       = @(320, 480)
  'drawable-port-hdpi'       = @(480, 800)
  'drawable-port-xhdpi'      = @(720, 1280)
  'drawable-port-xxhdpi'     = @(960, 1600)
  'drawable-port-xxxhdpi'    = @(1280, 1920)
}
foreach ($k in $splash.Keys) {
  $dir = Join-Path $res $k
  if (-not (Test-Path $dir)) { continue }
  $wh = $splash[$k]
  $bmp = New-Object System.Drawing.Bitmap($wh[0], $wh[1], [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $b = New-Object System.Drawing.SolidBrush($blue)
  $g.FillRectangle($b, 0, 0, $wh[0], $wh[1]); $b.Dispose()
  $s = [single](0.34 * [Math]::Min($wh[0], $wh[1]))
  Draw-Mark $g ([single](($wh[0] - $s) / 2)) ([single](($wh[1] - $s) / 2)) $s
  $g.Dispose()
  $p = Join-Path $dir 'splash.png'
  $bmp.Save($p, [System.Drawing.Imaging.ImageFormat]::Png)
  $bmp.Dispose()
  Write-Host ("  wrote $k/splash.png " + $wh[0] + "x" + $wh[1])
}

# The adaptive background is a colour resource, not a pixel file.
$bgFile = Join-Path $res 'values\ic_launcher_background.xml'
if (Test-Path $bgFile) {
  (Get-Content $bgFile -Raw -Encoding UTF8) -replace '#FFFFFF', '#1565C0' |
    Set-Content $bgFile -Encoding UTF8 -NoNewline
  Write-Host '  adaptive background -> #1565C0'
}

Write-Host 'icons done.'
